 save:'<path d="M4 3h13l4 4v14H3V3h1m3 0v7h10V3M7 21v-7h10v7"/>',plus:'<path d="M12 4v16M4 12h16"/>',
 folder:'<path d="M3 6h7l2 3h9v12H3z"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6"/>',
 tree:'<rect x="9" y="2" width="6" height="5" rx="1"/><path d="M12 7v5M5 16v-4h14v4"/><rect x="2" y="16" width="6" height="5" rx="1"/><rect x="16" y="16" width="6" height="5" rx="1"/>',
 code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',
 shield:'<path d="m12 2 9 4v7c0 5-9 9-9 9s-9-4-9-9V6z"/><path d="m8 12 3 3 5-6"/>',
 check:'<path d="m5 12 4 4 10-11"/>',filter:'<path d="M3 4h18l-7 8v8l-4-2v-6z"/>',
 refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',
 chart:'<path d="M3 3v18h18M7 16v-4M12 16V7M17 16v-7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 link:'<path d="m9 15 6-6m-8 9-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2-2 1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3 9 9 0 1 0 20 15z"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2M12 21v2M1 12h2M21 12h2M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 6v1"/>',undo:'<path d="M8 6H3v-5M3 6a9 9 0 1 1-1 10"/>',
